package com.bautruc.ecommerce.order.api.response;import com.bautruc.ecommerce.order.domain.OrderItem;public record OrderItemResponse(Long productId,String productNameVi,String productNameEn,long basePrice,long sellingPrice,int quantity,long totalPrice){public static OrderItemResponse from(OrderItem i){return new OrderItemResponse(i.getProductId(),i.getProductNameVi(),i.getProductNameEn(),i.getBasePrice(),i.getSellingPrice(),i.getQuantity(),i.getTotalPrice());}}
